def backfill_issue_numbers(apps, schema_editor):
    Issue = apps.get_model("issues", "Issue")
    IssueCounter = apps.get_model("issues", "IssueCounter")
    database = schema_editor.connection.alias
    allowed_points = {1, 2, 3, 5, 8, 13}

    Issue.objects.using(database).filter(status="todo").update(status="to_do")
    Issue.objects.using(database).filter(story_points__isnull=False).exclude(
        story_points__in=allowed_points
    ).update(story_points=None)

    project_ids = (
        Issue.objects.using(database)
        .order_by()
        .values_list("project_id", flat=True)
        .distinct()
    )
    for project_id in project_ids:
        used_numbers = set()
        issues = Issue.objects.using(database).filter(project_id=project_id).order_by(
            "created_at", "id"
        )
        for issue in issues:
            suffix = issue.key.rsplit("-", 1)[-1]
            number = int(suffix) if suffix.isdigit() else None
            if number is None or number < 1 or number in used_numbers:
                number = max(used_numbers, default=0) + 1
                while number in used_numbers:
                    number += 1
            used_numbers.add(number)
            Issue.objects.using(database).filter(pk=issue.pk).update(number=number)

        IssueCounter.objects.using(database).update_or_create(
            project_id=project_id,
            defaults={"next_number": max(used_numbers, default=0) + 1},
        )


